# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import gap_labels

OPEN = Span(540, 1020)


class GapTests(unittest.TestCase):
    def test_gap_between_spans(self):
        found = gap_labels([Span(540, 720), Span(780, 1020)], OPEN)
        self.assertEqual(found, ["gap 12:00-13:00 (60 min)"])

    def test_gaps_at_both_ends(self):
        found = gap_labels([Span(600, 900)], OPEN)
        self.assertEqual(found, ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"])

    def test_overlaps_leave_no_gap(self):
        self.assertEqual(gap_labels([Span(540, 800), Span(700, 1020)], OPEN), [])

    def test_nobody_working(self):
        self.assertEqual(gap_labels([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_span_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            gap_labels([Span(500, 600)], OPEN)
